before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>
#include <utility>
#include <vector>
int main() {
    std::vector<int> a{2, 4};
    auto b = std::move(a);
    a.clear();
    a.push_back(7);
    std::cout << b[0] << ' ' << a[0] << '\n';
}

```

